import { execSync } from "child_process";
import { writeFileSync } from "fs";
import { createForks, teardownForks } from "@tigrisdata/agent-kit";

async function main() {
  try {
    // 1. Detect prefix collisions
    console.log("Detecting prefix collisions...");
    const listOutput = execSync("tigris buckets list --json", { encoding: "utf-8" });
    const listData = JSON.parse(listOutput);

    const prefix = "eval-prefix";
    const collidingBuckets = listData.items
      .map((item: any) => item.name)
      .filter((name: string) => name.startsWith(prefix));

    // 2. Delete colliding buckets
    for (const bucket of collidingBuckets) {
      if (bucket === "source-bucket") continue; // safety check
      console.log(`Deleting colliding bucket: ${bucket}`);
      execSync(`tigris buckets delete ${bucket} --force`, { stdio: "inherit" });
    }

    // 3. Create forks
    console.log("Creating forks...");
    const { data: forkSet, error } = await createForks("source-bucket", 3, {
      prefix: prefix,
      credentials: { role: "Editor" }
    });

    if (error) {
      console.error("Error creating forks:", error);
      process.exit(1);
    }

    if (!forkSet || forkSet.forks.length !== 3) {
      console.error("Failed to create exactly 3 forks");
      process.exit(1);
    }

    // 4. Record fork names
    const forkNames = forkSet.forks.map(f => f.bucket);
    console.log("Created forks:", forkNames);

    writeFileSync(
      "/home/user/safe-fork/forks.json",
      JSON.stringify({ forks: forkNames }, null, 2)
    );
    console.log("Wrote forks.json");

    // 5. Tear down the new forks
    console.log("Tearing down forks...");
    await teardownForks(forkSet);
    console.log("Tear down complete. Exiting successfully.");

    process.exit(0);
  } catch (error) {
    console.error("Script failed:", error);
    process.exit(1);
  }
}

main();

